## 1. `mem.h` — 进程与模块

```cpp
#pragma once
#define WIN32_LEAN_AND_MEAN
#define NOMINMAX
#include <windows.h>
#include <tlhelp32.h>
#include <vector>
#include <string>
#include <cstdint>
#include <cstring>
#include <cstdlib>
#include <cctype>
#include <cmath>

struct Region { uintptr_t base; size_t size; };

class Process {
public:
    HANDLE    h          = nullptr;
    DWORD     pid        = 0;
    uintptr_t clientBase = 0;
    size_t    clientSize = 0;

    ~Process() { if (h) CloseHandle(h); }

    bool Attach(const wchar_t* exe = L"cs2.exe") {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPPROCESS, 0);
        if (snap == INVALID_HANDLE_VALUE) return false;
        PROCESSENTRY32W pe{}; pe.dwSize = sizeof(pe);
        bool found = false;
        for (BOOL ok = Process32FirstW(snap, &pe); ok; ok = Process32NextW(snap, &pe)) {
            if (_wcsicmp(pe.szExeFile, exe) == 0) { pid = pe.th32ProcessID; found = true; break; }
        }
        CloseHandle(snap);
        if (!found) return false;

        h = OpenProcess(PROCESS_VM_READ | PROCESS_QUERY_INFORMATION, FALSE, pid);
        if (!h) return false;
        return ResolveModule(L"client.dll");
    }

    bool ResolveModule(const wchar_t* name) {
        HANDLE snap = CreateToolhelp32Snapshot(TH32CS_SNAPMODULE | TH32CS_SNAPMODULE32, pid);
        if (snap == INVALID_HANDLE_VALUE) return false;
        MODULEENTRY32W me{}; me.dwSize = sizeof(me);
        bool ok = false;
        for (BOOL r = Module32FirstW(snap, &me); r; r = Module32NextW(snap, &me)) {
            if (_wcsicmp(me.szModule, name) == 0) {
                clientBase = (uintptr_t)me.modBaseAddr;
                clientSize = me.modBaseSize;
                ok = true; break;
            }
        }
        CloseHandle(snap);
        return ok;
    }

    template <typename T> T Read(uintptr_t addr) const {
        T v{};
        ReadProcessMemory(h, (LPCVOID)addr, &v, sizeof(T), nullptr);
        return v;
    }
    bool ReadBuf(uintptr_t addr, void* out, size_t n) const {
        SIZE_T got = 0;
        return ReadProcessMemory(h, (LPCVOID)addr, out, n, &got) && got == n;
    }
    // 逐字节读字符串，避免跨页失败
    bool ReadStr(uintptr_t addr, char* out, size_t cap) const {
        if (!addr) { out[0] = 0; return false; }
        for (size_t i = 0; i < cap; ++i) {
            char c = 0;
            if (!ReadProcessMemory(h, (LPCVOID)(addr + i), &c, 1, nullptr)) { out[i] = 0; return false; }
            out[i] = c;
            if (!c) return true;
        }
        out[cap - 1] = 0;
        return true;
    }
};

inline std::vector<Region> EnumReadableRegions(const Process& p, uintptr_t lo, uintptr_t hi) {
    std::vector<Region> out;
    uintptr_t addr = lo;
    MEMORY_BASIC_INFORMATION mbi{};
    while (addr < hi) {
        if (!VirtualQueryEx(p.h, (LPCVOID)addr, &mbi, sizeof(mbi))) break;
        uintptr_t rbase = (uintptr_t)mbi.BaseAddress;
        size_t    rsize = mbi.RegionSize;
        if (!rsize) break;
        DWORD prot = mbi.Protect;
        bool readable =
            mbi.State == MEM_COMMIT &&
            !(prot & (PAGE_GUARD | PAGE_NOACCESS)) &&
            (prot & (PAGE_READONLY | PAGE_READWRITE | PAGE_WRITECOPY |
                     PAGE_EXECUTE_READ | PAGE_EXECUTE_READWRITE | PAGE_EXECUTE_WRITECOPY));
        if (readable) out.push_back({ rbase, rsize });
        addr = rbase + rsize;
    }
    return out;
}
```

