## 2. `aob.h` — 模式扫描 + RIP 解析

IDA 风格通配符，首字节锚点 + `memchr` 跳扫；按 8 MB 分块读，块间留 `pat.size()-1` 重叠。

```cpp
#pragma once
#include "mem.h"
#include <cstring>

namespace aob {

struct Byte { uint8_t v; bool any; };

inline std::vector<Byte> Parse(const char* sig) {
    std::vector<Byte> out;
    for (const char* p = sig; *p; ) {
        if (*p == ' ' || *p == '\t') { ++p; continue; }
        if (*p == '?') {
            out.push_back({ 0, true });
            ++p; if (*p == '?') ++p;
            continue;
        }
        if (isxdigit((unsigned char)p[0]) && isxdigit((unsigned char)p[1])) {
            char b[3] = { p[0], p[1], 0 };
            out.push_back({ (uint8_t)strtoul(b, nullptr, 16), false });
            p += 2;
            continue;
        }
        return {};                     // 非法签名
    }
    return out;
}

inline size_t FindIn(const uint8_t* data, size_t size, const std::vector<Byte>& pat, size_t start = 0) {
    if (pat.empty() || size < pat.size()) return SIZE_MAX;
    size_t anchor = 0;
    while (anchor < pat.size() && pat[anchor].any) ++anchor;
    if (anchor == pat.size() || start > size - pat.size()) return SIZE_MAX;

    size_t last = size - pat.size();   // 最后一个合法起始下标
    size_t i    = start;
    while (i <= last) {
        const uint8_t* from = data + i + anchor;
        const uint8_t* end  = data + last + anchor + 1;
        const uint8_t* hit  = (const uint8_t*)memchr(from, pat[anchor].v, (size_t)(end - from));
        if (!hit) return SIZE_MAX;
        size_t pos = (size_t)(hit - data) - anchor;
        bool ok = true;
        for (size_t k = 0; k < pat.size(); ++k) {
            if (!pat[k].any && data[pos + k] != pat[k].v) { ok = false; break; }
        }
        if (ok) return pos;
        i = pos + 1;
    }
    return SIZE_MAX;
}

// 在 [base, base+size) 的可读区段内扫描，返回绝对地址
inline uintptr_t ScanModule(const Process& p, uintptr_t base, size_t size,
                            const char* sig, int hitIndex = 0) {
    auto pat = Parse(sig);
    if (pat.empty()) return 0;

    const size_t CHUNK   = 8u << 20;
    const size_t overlap = pat.size() - 1;
    int seen = 0;

    for (auto& r : EnumReadableRegions(p, base, base + size)) {
        for (size_t off = 0; off < r.size; off += CHUNK) {
            size_t n = r.size - off;
            if (n > CHUNK + overlap) n = CHUNK + overlap;
            std::vector<uint8_t> buf(n);
            if (!p.ReadBuf(r.base + off, buf.data(), n)) break;

            size_t cursor = 0;
            while (true) {
                size_t pos = FindIn(buf.data(), buf.size(), pat, cursor);
                if (pos == SIZE_MAX) break;
                if (off > 0 && pos < overlap) { cursor = pos + 1; continue; } // 上一块已覆盖
                if (seen++ >= hitIndex) return r.base + off + pos;
                cursor = pos + 1;
            }
            if (n < CHUNK + overlap) break;
        }
    }
    return 0;
}

// 解析 x86-64 RIP 相对寻址： instrAddr 指向指令首字节
inline uintptr_t Rip(const Process& p, uintptr_t instrAddr, int dispOffset, int instrLen) {
    int32_t d = 0;
    if (!p.ReadBuf(instrAddr + dispOffset, &d, 4)) return 0;
    return instrAddr + instrLen + (intptr_t)d;
}

} // namespace aob
```

