## 3. `cs2.h` — 偏移、实体系统、W2S、自举定位

```cpp
#pragma once
#include "mem.h"
#include "aob.h"
#include <fstream>
#include <sstream>
#include <unordered_map>
#include <vector>
#include <string>
#include <cmath>

struct Vec3 { float x, y, z; };
struct Vec2 { float x, y; };
struct ViewMatrix { float m[4][4]; };

struct Offsets {
    // ---- client.dll 全局 ----
    uintptr_t dwEntityList        = 0x1A17B60;   // CANDIDATE
    uintptr_t dwViewMatrix        = 0x1A5C130;   // CANDIDATE
    uintptr_t dwLocalPlayerPawn   = 0x1A0F3C8;   // CANDIDATE

    // ---- schema (netvar) CANDIDATE ----
    uint32_t m_iHealth              = 0x344;
    uint32_t m_iTeamNum             = 0x3CB;
    uint32_t m_lifeState            = 0x338;
    uint32_t m_pGameSceneNode       = 0x328;
    uint32_t m_bDormant             = 0xEF;
    uint32_t m_hPlayerPawn          = 0x7EC;   // CBasePlayerController
    uint32_t m_sSanitizedPlayerName = 0x7B8;   // CBasePlayerController::m_sSanitizedPlayerName (CUtlString)
    uint32_t m_vecAbsOrigin         = 0x80;    // CGameSceneNode::m_vecAbsOrigin

    // ---- CGameEntitySystem 布局 ----
    uint32_t listChunkOff    = 0x10;  // sys + 0x10 -> 块指针数组
    uint32_t listChunkStride = 0x08;
    uint32_t listEntryStride = 0x70;
    uint32_t listIndexMask   = 0x1FF;
    uint32_t listChunkShift  = 9;
};

// ---------------- offsets.ini ----------------
inline std::string Trim(std::string s) {
    size_t a = s.find_first_not_of(" \t\r\n");
    if (a == std::string::npos) return "";
    size_t b = s.find_last_not_of(" \t\r\n");
    return s.substr(a, b - a + 1);
}

inline int LoadOffsets(const char* path, Offsets& o) {
    std::ifstream f(path);
    if (!f) return -1;
    std::unordered_map<std::string, uint64_t> kv;
    std::string line;
    while (std::getline(f, line)) {
        size_t c = line.find_first_of("#;");
        if (c != std::string::npos) line = line.substr(0, c);
        size_t eq = line.find('=');
        if (eq == std::string::npos) continue;
        std::string k = Trim(line.substr(0, eq));
        std::string v = Trim(line.substr(eq + 1));
        if (k.empty() || v.empty()) continue;
        kv[k] = strtoull(v.c_str(), nullptr, 0);
    }
    auto get = [&](const char* k, auto& dst) {
        auto it = kv.find(k);
        if (it != kv.end()) dst = (std::decay_t<decltype(dst)>)it->second;
    };
    get("dwEntityList",              o.dwEntityList);
    get("dwViewMatrix",              o.dwViewMatrix);
    get("dwLocalPlayerPawn",         o.dwLocalPlayerPawn);
    get("m_iHealth",                 o.m_iHealth);
    get("m_iTeamNum",                o.m_iTeamNum);
    get("m_lifeState",               o.m_lifeState);
    get("m_pGameSceneNode",          o.m_pGameSceneNode);
    get("m_bDormant",                o.m_bDormant);
    get("m_hPlayerPawn",             o.m_hPlayerPawn);
    get("m_sSanitizedPlayerName",    o.m_sSanitizedPlayerName);
    get("m_vecAbsOrigin",            o.m_vecAbsOrigin);
    get("listChunkOff",              o.listChunkOff);
    get("listChunkStride",           o.listChunkStride);
    get("listEntryStride",           o.listEntryStride);
    get("listIndexMask",             o.listIndexMask);
    get("listChunkShift",            o.listChunkShift);
    return (int)kv.size();
}

// ---------------- 数学 ----------------
inline bool Solve3(const double A[3][3], const double b[3], double out[3]) {
    double det = A[0][0]*(A[1][1]*A[2][2]-A[1][2]*A[2][1])
               - A[0][1]*(A[1][0]*A[2][2]-A[1][2]*A[2][0])
               + A[0][2]*(A[1][0]*A[2][1]-A[1][1]*A[2][0]);
    if (fabs(det) < 1e-12) return false;
    double inv[3][3];
    inv[0][0] =  (A[1][1]*A[2][2]-A[1][2]*A[2][1]) / det;
    inv[0][1] = -(A[0][1]*A[2][2]-A[0][2]*A[2][1]) / det;
    inv[0][2] =  (A[0][1]*A[1][2]-A[0][2]*A[1][1]) / det;
    inv[1][0] = -(A[1][0]*A[2][2]-A[1][2]*A[2][0]) / det;
    inv[1][1] =  (A[0][0]*A[2][2]-A[0][2]*A[2][0]) / det;
    inv[1][2] = -(A[0][0]*A[1][2]-A[0][2]*A[1][0]) / det;
    inv[2][0] =  (A[1][0]*A[2][1]-A[1][1]*A[2][0]) / det;
    inv[2][1] = -(A[0][0]*A[2][1]-A[0][1]*A[2][0]) / det;
    inv[2][2] =  (A[0][0]*A[1][1]-A[0][1]*A[1][0]) / det;
    for (int i = 0; i < 3; ++i)
        out[i] = inv[i][0]*b[0] + inv[i][1]*b[1] + inv[i][2]*b[2];
    return true;
}

// CS2 视图矩阵行 0..2 为相机正交基，行 3 为平移
inline bool PlausibleViewMatrix(const ViewMatrix& vm) {
    for (int i = 0; i < 16; ++i)
        if (!std::isfinite((&vm.m[0][0])[i]) || fabsf((&vm.m[0][0])[i]) > 1e5f) return false;

    float r0[3] = { vm.m[0][0], vm.m[0][1], vm.m[0][2] };
    float r1[3] = { vm.m[1][0], vm.m[1][1], vm.m[1][2] };
    float r2[3] = { vm.m[2][0], vm.m[2][1], vm.m[2][2] };
    auto len = [](const float* v) { return sqrtf(v[0]*v[0] + v[1]*v[1] + v[2]*v[2]); };
    auto dot = [](const float* a, const float* b) { return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; };

    if (fabsf(len(r0) - 1.f) > 0.05f) return false;
    if (fabsf(len(r1) - 1.f) > 0.05f) return false;
    if (fabsf(len(r2) - 1.f) > 0.05f) return false;
    if (fabsf(dot(r0, r1)) > 0.05f) return false;
    if (fabsf(dot(r0, r2)) > 0.05f) return false;
    if (fabsf(dot(r1, r2)) > 0.05f) return false;
    if (fabsf(vm.m[3][3] - 1.f) > 0.01f) return false;
    return true;
}

inline bool CameraFromViewMatrix(const ViewMatrix& vm, Vec3& eye) {
    double A[3][3] = {
        { vm.m[0][0], vm.m[0][1], vm.m[0][2] },
        { vm.m[1][0], vm.m[1][1], vm.m[1][2] },
        { vm.m[2][0], vm.m[2][1], vm.m[2][2] } };
    double b[3] = { -vm.m[0][3], -vm.m[1][3], -vm.m[2][3] };
    double s[3];
    if (!Solve3(A, b, s)) return false;
    eye = { (float)s[0], (float)s[1], (float)s[2] };
    return true;
}

inline bool WorldToScreen(const Vec3& w, const ViewMatrix& vm, int sw, int sh, Vec2& out) {
    float cw = vm.m[3][0]*w.x + vm.m[3][1]*w.y + vm.m[3][2]*w.z + vm.m[3][3];
    if (cw < 0.001f) return false;                        // 在相机背后
    float cx = vm.m[0][0]*w.x + vm.m[0][1]*w.y + vm.m[0][2]*w.z + vm.m[0][3];
    float cy = vm.m[1][0]*w.x + vm.m[1][1]*w.y + vm.m[1][2]*w.z + vm.m[1][3];
    float iw = 1.0f / cw;
    out.x = (sw * 0.5f) * (1.0f + cx * iw);
    out.y = (sh * 0.5f) * (1.0f - cy * iw);
    return true;
}

// ---------------- 实体 ----------------
struct Player {
    uintptr_t pawn = 0, controller = 0;
    int   health = 0, team = 0;
    Vec3  origin{};
    char  name[64]{};
};

struct Snapshot {
    bool  haveLocal = false;
    Vec3  localOrigin{};
    int   localTeam = 0;
    std::vector<Player> players;
};

class CGame {
public:
    Process* p = nullptr;
    Offsets  o{};

    uintptr_t entitySystem() const {
        return p->Read<uintptr_t>(p->clientBase + o.dwEntityList);
    }

    // handle = (chunk << 9) | index
    uintptr_t entityFromHandle(uint32_t handle) const {
        if (!handle || handle == 0xFFFFFFFFu) return 0;
        uintptr_t sys = entitySystem();
        if (!sys) return 0;
        uintptr_t chunk = p->Read<uintptr_t>(
            sys + o.listChunkOff + o.listChunkStride * (handle >> o.listChunkShift));
        if (!chunk) return 0;
        return p->Read<uintptr_t>(chunk + o.listEntryStride * (handle & o.listIndexMask));
    }

    Vec3 originOf(uintptr_t pawn) const {
        uintptr_t node = p->Read<uintptr_t>(pawn + o.m_pGameSceneNode);
        if (!node) return {};
        return p->Read<Vec3>(node + o.m_vecAbsOrigin);
    }

    Snapshot Take(int maxIndex = 64, bool teamFilter = true, bool localOnly = false) const {
        Snapshot s;
        uintptr_t localPawn = p->Read<uintptr_t>(p->clientBase + o.dwLocalPlayerPawn);
        if (localPawn) {
            s.haveLocal   = true;
            s.localOrigin = originOf(localPawn);
            s.localTeam   = p->Read<int>(localPawn + o.m_iTeamNum);
        }

        for (int i = 1; i <= maxIndex; ++i) {
            uintptr_t ctrl = entityFromHandle((uint32_t)i);
            if (!ctrl) continue;
            uint32_t hPawn = p->Read<uint32_t>(ctrl + o.m_hPlayerPawn);
            uintptr_t pawn = entityFromHandle(hPawn);
            if (!pawn || pawn == localPawn) continue;

            int health = p->Read<int>(pawn + o.m_iHealth);
            int team   = p->Read<int>(pawn + o.m_iTeamNum);
            uint8_t life = p->Read<uint8_t>(pawn + o.m_lifeState);
            bool dormant = p->Read<uint8_t>(pawn + o.m_bDormant) != 0;
            if (dormant || life != 0 || health <= 0 || health > 100) continue;
            if (team != 2 && team != 3) continue;
            if (teamFilter && s.haveLocal && team == s.localTeam) continue;

            Vec3 org = originOf(pawn);
            if (!std::isfinite(org.x) || fabsf(org.x) > 16384.f) continue;

            Player pl;
            pl.pawn = pawn; pl.controller = ctrl;
            pl.health = health; pl.team = team; pl.origin = org;
            uintptr_t namePtr = p->Read<uintptr_t>(ctrl + o.m_sSanitizedPlayerName);
            if (namePtr) p->ReadStr(namePtr, pl.name, sizeof(pl.name));
            s.players.push_back(pl);
        }
        return s;
    }
};
```

### 3.1 自举定位（无 ini / 版本更新后重算）

三段式，全部带结构校验，不依赖硬编码签名：

```cpp
// ① 实体系统：在 client.dll 可写段里找指针槽 P，
//    要求 [P+0x10] 可读，且该块前几个元素指向 client.dll 内部的 vtable
inline uintptr_t FindEntitySystemSlot(const Process& p, uintptr_t base, size_t size, const Offsets& o) {
    for (auto& r : EnumReadableRegions(p, base, base + size)) {
        std::vector<uint8_t> buf(r.size);
        if (!p.ReadBuf(r.base, buf.data(), buf.size())) continue;
        for (size_t i = 0; i + 8 <= buf.size(); i += 8) {
            uintptr_t cand = *(uintptr_t*)(buf.data() + i);
            if (cand < 0x10000 || (cand >> 47)) continue;          // 必须是用户态指针
            uintptr_t chunk0 = 0;
            if (!p.ReadBuf(cand + o.listChunkOff, &chunk0, 8) || !chunk0) continue;
            uintptr_t probe[4] = {};
            if (!p.ReadBuf(chunk0, probe, sizeof(probe))) continue;
            int good = 0;
            for (uintptr_t ent : probe) {
                if (!ent) continue;
                uintptr_t vt = 0;
                if (!p.ReadBuf(ent, &vt, 8)) continue;
                if (vt >= base && vt < base + size) ++good;        // vtable 落在 client.dll
            }
            if (good >= 2) return r.base + i;                      // 返回槽地址 = base + 偏移
        }
    }
    return 0;
}

// ② 视图矩阵：行 0..2 正交归一 + m[3][3]≈1
inline std::vector<uintptr_t> FindViewMatrixCandidates(const Process& p, uintptr_t base, size_t size) {
    std::vector<uintptr_t> out;
    for (auto& r : EnumReadableRegions(p, base, base + size)) {
        std::vector<uint8_t> buf(r.size);
        if (!p.ReadBuf(r.base, buf.data(), buf.size())) continue;
        for (size_t i = 0; i + 64 <= buf.size(); i += 4) {
            ViewMatrix vm;
            memcpy(&vm, buf.data() + i, 64);
            if (PlausibleViewMatrix(vm)) out.push_back(r.base + i);
        }
    }
    return out;
}

// ③ 本地玩家：由视图矩阵反算相机世界坐标，取离相机最近的 pawn
inline uintptr_t FindLocalPawnByCamera(const CGame& g, const ViewMatrix& vm) {
    Vec3 eye{};
    if (!CameraFromViewMatrix(vm, eye)) return 0;
    uintptr_t best = 0; float bestD = 1e9f;
    for (int i = 1; i <= 64; ++i) {
        uintptr_t ctrl = g.entityFromHandle((uint32_t)i);
        if (!ctrl) continue;
        uintptr_t pawn = g.entityFromHandle(g.p->Read<uint32_t>(ctrl + g.o.m_hPlayerPawn));
        if (!pawn) continue;
        Vec3 org = g.originOf(pawn);
        float dz = fabsf(org.z - eye.z);
        if (dz > 90.f) continue;                       // 站/蹲视高差
        float dh = sqrtf((org.x-eye.x)*(org.x-eye.x) + (org.y-eye.y)*(org.y-eye.y));
        if (dh > 48.f) continue;
        if (dh + dz * 0.25f < bestD) { bestD = dh + dz * 0.25f; best = pawn; }
    }
    return best;
}

// 汇总：ini 缺失/失效时调用，写回 Offsets
inline void Bootstrap(CGame& g, bool verbose) {
    Process& p = *g.p;
    if (verbose) printf("[*] bootstrap: client.dll %p size 0x%zX\n", (void*)p.clientBase, p.clientSize);

    uintptr_t slot = FindEntitySystemSlot(p, p.clientBase, p.clientSize, g.o);
    if (slot) { g.o.dwEntityList = slot - p.clientBase;
                if (verbose) printf("[+] dwEntityList = 0x%llX\n", (unsigned long long)g.o.dwEntityList); }

    for (uintptr_t vmAddr : FindViewMatrixCandidates(p, p.clientBase, p.clientSize)) {
        ViewMatrix vm = p.Read<ViewMatrix>(vmAddr);
        Vec3 eye{};
        if (!CameraFromViewMatrix(vm, eye)) continue;
        if (!std::isfinite(eye.x) || fabsf(eye.x) > 32768.f) continue;   // 地图边界内
        g.o.dwViewMatrix = vmAddr - p.clientBase;
        if (verbose) printf("[+] dwViewMatrix = 0x%llX  cam=(%.1f %.1f %.1f)\n",
                            (unsigned long long)g.o.dwViewMatrix, eye.x, eye.y, eye.z);
        uintptr_t lp = FindLocalPawnByCamera(g, vm);
        if (lp) {
            uintptr_t cur = p.Read<uintptr_t>(p.clientBase + g.o.dwLocalPlayerPawn);
            if (cur != lp) {
                // 反查指针槽
                for (auto& r : EnumReadableRegions(p, p.clientBase, p.clientBase + p.clientSize)) {
                    std::vector<uint8_t> buf(r.size);
                    if (!p.ReadBuf(r.base, buf.data(), buf.size())) continue;
                    for (size_t i = 0; i + 8 <= buf.size(); i += 8) {
                        if (*(uintptr_t*)(buf.data() + i) == lp) {
                            g.o.dwLocalPlayerPawn = (r.base + i) - p.clientBase;
                            goto found_local;
                        }
                    }
                }
            found_local:;
            }
            if (verbose) printf("[+] dwLocalPlayerPawn = 0x%llX (pawn %p)\n",
                                (unsigned long long)g.o.dwLocalPlayerPawn, (void*)lp);
        }
        return;
    }
}
