class Overlay {
public:
    int  x = 0, y = 0, w = 0, h = 0;
    HWND hwnd = nullptr;

    bool Create() {
        Gdiplus::GdiplusStartupInput si;
        Gdiplus::GdiplusStartup(&gdiToken_, &si, nullptr);

        x = GetSystemMetrics(SM_XVIRTUALSCREEN);
        y = GetSystemMetrics(SM_YVIRTUALSCREEN);
        w = GetSystemMetrics(SM_CXVIRTUALSCREEN);
        h = GetSystemMetrics(SM_CYVIRTUALSCREEN);

        WNDCLASSEXW wc{}; wc.cbSize = sizeof(wc);
        wc.lpfnWndProc   = DefWindowProcW;
        wc.hInstance     = GetModuleHandleW(nullptr);
        wc.lpszClassName = L"cs2_esp_overlay";
        wc.hCursor       = LoadCursor(nullptr, IDC_ARROW);
        RegisterClassExW(&wc);

        hwnd = CreateWindowExW(
            WS_EX_TOPMOST | WS_EX_TRANSPARENT | WS_EX_LAYERED |
            WS_EX_TOOLWINDOW | WS_EX_NOACTIVATE,
            wc.lpszClassName, L"", WS_POPUP, x, y, w, h,
            nullptr, nullptr, wc.hInstance, nullptr);
        if (!hwnd) return false;

        SetWindowPos(hwnd, HWND_TOPMOST, x, y, w, h, SWP_NOACTIVATE | SWP_SHOWWINDOW);
        ShowWindow(hwnd, SW_SHOWNOACTIVATE);
        // 禁止被 OBS / 截图 API 抓到（本身也是可检测特征，按需注释掉）
        SetWindowDisplayAffinity(hwnd, 0x00000011 /* WDA_EXCLUDEFROMCAPTURE */);

        screenDC_ = GetDC(nullptr);
        BITMAPINFO bmi{};
        bmi.bmiHeader.biSize        = sizeof(BITMAPINFOHEADER);
        bmi.bmiHeader.biWidth       = w;
        bmi.bmiHeader.biHeight      = -h;              // top-down
        bmi.bmiHeader.biPlanes      = 1;
        bmi.bmiHeader.biBitCount    = 32;
        bmi.bmiHeader.biCompression = BI_RGB;
        dib_ = CreateDIBSection(screenDC_, &bmi, DIB_RGB_COLORS, &bits_, nullptr, 0);
        if (!dib_) return false;

        memDC_  = CreateCompatibleDC(screenDC_);
        oldBmp_ = SelectObject(memDC_, dib_);
        g_      = new Gdiplus::Graphics(memDC_);
        g_->SetSmoothingMode(Gdiplus::SmoothingModeAntiAlias);
        g_->SetTextRenderingHint(Gdiplus::TextRenderingHintAntiAlias);
        fBig_   = new Gdiplus::Font(L"Consolas", 14.f, Gdiplus::FontStyleRegular, Gdiplus::UnitPixel);
        fSmall_ = new Gdiplus::Font(L"Consolas", 12.f, Gdiplus::FontStyleRegular, Gdiplus::UnitPixel);
        return true;
    }

    void Destroy() {
        delete g_; delete fBig_; delete fSmall_;
        if (memDC_) { SelectObject(memDC_, oldBmp_); DeleteDC(memDC_); }
        if (dib_)   DeleteObject(dib_);
        if (screenDC_) ReleaseDC(nullptr, screenDC_);
        if (hwnd) DestroyWindow(hwnd);
        if (gdiToken_) Gdiplus::GdiplusShutdown(gdiToken_);
    }

    void BeginFrame() { g_->Clear(Gdiplus::Color(0, 0, 0, 0)); }

    void EndFrame() {
        POINT src{ 0, 0 }, dst{ x, y };
        SIZE  sz{ w, h };
        BLENDFUNCTION bf{ AC_SRC_OVER, 0, 255, AC_SRC_ALPHA };
        UpdateLayeredWindow(hwnd, screenDC_, &dst, &sz, memDC_, &src, 0, &bf, ULW_ALPHA);
    }

    void Box(float x0, float y0, float x1, float y1, Gdiplus::Color c, float t = 1.5f) {
        Gdiplus::Pen pen(c, t);
        g_->DrawRectangle(&pen, x0, y0, x1 - x0, y1 - y0);
    }
    void Fill(float bx, float by, float bw, float bh, Gdiplus::Color c) {
        Gdiplus::SolidBrush br(c);
        g_->FillRectangle(&br, bx, by, bw, bh);
    }
    void Text(const wchar_t* s, float tx, float ty, Gdiplus::Color c, bool small = false) {
        Gdiplus::SolidBrush br(c);
        g_->DrawString(s, -1, small ? fSmall_ : fBig_, Gdiplus::PointF(tx, ty), &br);
    }

private:
    ULONG_PTR gdiToken_ = 0;
    HDC screenDC_ = nullptr, memDC_ = nullptr;
    HBITMAP dib_ = nullptr;
    HGDIOBJ oldBmp_ = nullptr;
    void* bits_ = nullptr;
    Gdiplus::Graphics* g_ = nullptr;
    Gdiplus::Font* fBig_ = nullptr;
    Gdiplus::Font* fSmall_ = nullptr;
};
