## 5. `main.cpp` — 主循环 + dump 模式

```cpp
#include "cs2.h"
#include "overlay.h"
#include <thread>
#include <atomic>
#include <cstdio>

static std::atomic<bool> g_espOn{ true };

static void PumpMessages() {
    MSG msg;
    while (PeekMessageW(&msg, nullptr, 0, 0, PM_REMOVE)) {
        TranslateMessage(&msg);
        DispatchMessageW(&msg);
    }
}

static bool KeyPressedOnce(int vk) {
    static bool state[256]{};
    bool now = (GetAsyncKeyState(vk) & 0x8000) != 0;
    bool fire = now && !state[vk];
    state[vk] = now;
    return fire;
}

static void RenderLoop(CGame& game, Overlay& ov) {
    Process& p = *game.p;
    for (;;) {
        PumpMessages();
        if (KeyPressedOnce(VK_INSERT)) g_espOn = !g_espOn;

        ov.BeginFrame();
        if (g_espOn) {
            ViewMatrix vm = p.Read<ViewMatrix>(p.clientBase + game.o.dwViewMatrix);
            Snapshot snap = game.Take();

            for (auto& pl : snap.players) {
                Vec3 headPos{ pl.origin.x, pl.origin.y, pl.origin.z + 72.f };
                Vec2 head{}, feet{};
                if (!WorldToScreen(headPos, vm, ov.w, ov.h, head)) continue;
                if (!WorldToScreen(pl.origin, vm, ov.w, ov.h, feet)) continue;

                float boxH = feet.y - head.y;
                if (boxH < 4.f || boxH > ov.h * 1.5f) continue;
                float boxW = boxH * 0.42f;
                float x0 = head.x - boxW * 0.5f, x1 = head.x + boxW * 0.5f;

                Gdiplus::Color col = (pl.team == 3)
                    ? Gdiplus::Color(255, 90, 170, 255)
                    : Gdiplus::Color(255, 255, 110, 90);

                ov.Box(x0, head.y, x1, feet.y, col, 1.5f);

                // 血条
                float frac = pl.health / 100.f;
                float barW = 3.f, barH = feet.y - head.y;
                ov.Fill(x0 - barW - 3.f, feet.y - barH, barW, barH,
                        Gdiplus::Color(140, 0, 0, 0));
                ov.Fill(x0 - barW - 3.f, feet.y - barH * frac, barW, barH * frac,
                        Gdiplus::Color(255, (int)(255 * (1 - frac)), (int)(255 * frac), 60));

                // 名字 + 距离（1 unit ≈ 1.905 cm）
                float distM = 0.f;
                if (snap.haveLocal) {
                    float dx = pl.origin.x - snap.localOrigin.x;
                    float dy = pl.origin.y - snap.localOrigin.y;
                    float dz = pl.origin.z - snap.localOrigin.z;
                    distM = sqrtf(dx*dx + dy*dy + dz*dz) * 0.01905f;
                }
                wchar_t line[128];
                wchar_t wname[64] = L"?";
                MultiByteToWideChar(CP_UTF8, 0, pl.name, -1, wname, 64);
                swprintf_s(line, L"%s  [%.0fm]", wname, distM);
                ov.Text(line, x0, head.y - 18.f, Gdiplus::Color(255, 235, 235, 235), true);
            }
        }
        ov.EndFrame();
        Sleep(1);
    }
}

static void DumpMode(CGame& game) {
    Process& p = *game.p;
    printf("client.dll  base=%p  size=0x%zX\n", (void*)p.clientBase, p.clientSize);
    printf("dwEntityList      = 0x%llX -> %p\n",
           (unsigned long long)game.o.dwEntityList, (void*)game.entitySystem());

    ViewMatrix vm = p.Read<ViewMatrix>(p.clientBase + game.o.dwViewMatrix);
    printf("dwViewMatrix      = 0x%llX  plausible=%d\n",
           (unsigned long long)game.o.dwViewMatrix, (int)PlausibleViewMatrix(vm));
    Vec3 eye{};
    if (CameraFromViewMatrix(vm, eye))
        printf("  camera eye      = (%.1f, %.1f, %.1f)\n", eye.x, eye.y, eye.z);
    printf("  m00=%.4f m11=%.4f m22=%.4f m33=%.4f\n",
           vm.m[0][0], vm.m[1][1], vm.m[2][2], vm.m[3][3]);

    uintptr_t lp = p.Read<uintptr_t>(p.clientBase + game.o.dwLocalPlayerPawn);
    printf("dwLocalPlayerPawn = 0x%llX -> %p\n",
           (unsigned long long)game.o.dwLocalPlayerPawn, (void*)lp);
    if (lp) {
        printf("  health=%d team=%d origin=(%.1f %.1f %.1f)\n",
               p.Read<int>(lp + game.o.m_iHealth),
               p.Read<int>(lp + game.o.m_iTeamNum),
               game.originOf(lp).x, game.originOf(lp).y, game.originOf(lp).z);
    }

    Snapshot s = game.Take(64, /*teamFilter=*/false);
    printf("entities: %zu\n", s.players.size());
    for (auto& pl : s.players)
        printf("  [%p] hp=%3d team=%d  (%.1f %.1f %.1f)  %s\n",
               (void*)pl.pawn, pl.health, pl.team,
               pl.origin.x, pl.origin.y, pl.origin.z, pl.name);
}

int wmain(int argc, wchar_t** argv) {
    Process p;
    if (!p.Attach(L"cs2.exe")) { printf("[-] cs2.exe 未找到\n"); return 1; }

    CGame game; game.p = &p;
    int n = LoadOffsets("offsets.ini", game.o);
    printf("[*] offsets.ini: %s (%d keys)\n", n > 0 ? "loaded" : "missing", n);

    bool dump = (argc > 1 && _wcsicmp(argv[1], L"dump") == 0);
    bool force = (argc > 1 && _wcsicmp(argv[1], L"rebase") == 0);

    // 校验 ini 里的 client 偏移；失效则自举
    ViewMatrix vm = p.Read<ViewMatrix>(p.clientBase + game.o.dwViewMatrix);
    bool vmOk = PlausibleViewMatrix(vm);
    uintptr_t sys = game.entitySystem();
    bool sysOk = sys && p.Read<uintptr_t>(sys + game.o.listChunkOff) != 0;
    uintptr_t lp = p.Read<uintptr_t>(p.clientBase + game.o.dwLocalPlayerPawn);
    bool pawnOk = lp && p.Read<int>(lp + game.o.m_iHealth) <= 100;

    printf("[*] validate: vm=%d entityList=%d localPawn=%d\n", vmOk, sysOk, pawnOk);
    if (force || !vmOk || !sysOk) Bootstrap(game, true);

    if (dump) { DumpMode(game); return 0; }

    Overlay ov;
    if (!ov.Create()) { printf("[-] overlay 创建失败\n"); return 1; }
    printf("[*] overlay %dx%d @ (%d,%d)  INSERT 开关, END 退出\n", ov.w, ov.h, ov.x, ov.y);

    RenderLoop(game, ov);
    ov.Destroy();
    return 0;
}
