`gen_offsets.py`：

```python
#!/usr/bin/env python3
"""cs2-dumper 输出 -> offsets.ini"""
import json, os, sys

root = sys.argv[1] if len(sys.argv) > 1 else "."
want_off = ["dwEntityList", "dwViewMatrix", "dwLocalPlayerPawn"]
want_sch = ["m_iHealth", "m_iTeamNum", "m_lifeState", "m_pGameSceneNode",
            "m_bDormant", "m_hPlayerPawn", "m_sSanitizedPlayerName", "m_vecAbsOrigin"]

offs, sch = {}, {}
p = os.path.join(root, "offsets.json")
if os.path.exists(p):
    def walk(node):
        if isinstance(node, dict):
            for k, v in node.items(): walk(v)
        elif isinstance(node, int) and node > 0:
            pass
    def collect(node, key=None):
        if isinstance(node, dict):
            for k, v in node.items(): collect(v, k)
        elif isinstance(node, int) and key in want_off:
            offs[key] = node
    collect(json.load(open(p)))

p = os.path.join(root, "client_dll.json")
if os.path.exists(p):
    d = json.load(open(p))
    for mod in d.values():
        for cname, c in mod.get("classes", {}).items():
            for fname, f in c.get("fields", {}).items():
                if fname in want_sch:
                    sch.setdefault(fname, f["offset"])

with open(os.path.join(root, "offsets.ini"), "w") as f:
    f.write("# generated by gen_offsets.py\n")
    for k in want_off:
        if k in offs: f.write(f"{k} = 0x{offs[k]:X}\n")
    f.write("\n")
    for k in want_sch:
        if k in sch: f.write(f"{k} = 0x{sch[k]:X}\n")
    f.write("\nlistChunkOff = 0x10\nlistChunkStride = 0x08\n"
            "listEntryStride = 0x70\nlistIndexMask = 0x1FF\nlistChunkShift = 9\n")
print("wrote offsets.ini")
```

